-- EVT hook file for shop_menu_buy (VRFW_Host handlers, docs/framework/lua-hosts.md). Graft util_shop_filter (util_sf_shop.lua). Generated by research/scripts/menu_assemble.py; do not edit by hand.
-- Utilities shop_filter, shop side (docs/game/modes/tienda-general.md §15). In a shop tab whose goods have retail
-- filter categories, the grey end of the tab bar shows the retail filter icon + <CMD_FUNC2> (Tab), like the bank; the
-- key opens the retail item filter window (item_filter_menu, the one of the equipment / kit / emblem / move lists)
-- with the tabs of that kind of goods, and its accept button filters the rows of the tab. Tab -> window (inventory):
--   boots / bracelets / pendants / specials (slot 4-7) -> stat tab (the 7 stats)              inventory 0-3
--   kits (slot 2) / emblems (slot 3)                    -> series tab (the 9 series)            inventory 4 / 5
--   special moves (slot 16)                             -> tension, element, skill type tabs    inventory 6
--   auras / hyper moves (slot 17)                       -> element, category tabs               inventory 11
-- Other tabs (tickets, items, titles, tactics, cards...) have no retail category: no button. utilities.dll
-- (crates/plugins/utilities/src/shop_filter) skips the rows the engine's own item test rejects when the tab is built
-- and counts the tab's rows for the window's counter (window side: item_filter_menu, util_sf_window.lua). The filter
-- of each tab lasts while the shop is open (UTIL_SF_PARAMS; the plugin's filters dropped on open / close). Rows other
-- mods grey out (Inazuma Fantasy's locked rows) are filtered like any row and keep their look.
--
-- Hook file (graft [[hooks]], never merged with other grafts): the callbacks are wrapped with handlers of the
-- VR-Framework's host of shop_menu_buy (menu_engine lua\shop_menu_buy\000_host.lua). Utilities is lua_early: its
-- handlers are registered before the host installs its dispatchers on top of every lua_early patch (Inazuma Fantasy's
-- merged shop_menu_buy file redefines OnShopInit / Step / OnSetupLayer / OnOpenLayer with promoted locals), so they
-- run around everything IF made of those functions. Without the host the globals are wrapped directly. Clean HUD's
-- shop shortcuts (L2 / R2 leave the shop: CLEAN_HUD_SS_CO) are read softly: nil without Clean HUD.
--
-- Banner (Nacho 28/09): the picture at the top right of the shops (layer shop01_11_view_staff, the SHOP_INFO header
-- texture cols 18/19 put into mesh _shop_cut_chr_dmy01 by OnSetupLayer and shown with _shop_cut_parts01) loads
-- asynchronously, so after a shop change the recycled picture could show the previous shop's art. The layer is hidden
-- in every shop and kept hidden (setup, open, and every 20 frames of Step); the header (mainmenu90_01_header: title
-- bar, shop name, mode icon) is not touched. No engine call at load time.
UTIL_SF_SHOP = 3170360552 --[[shop_menu]]
UTIL_SF_MENU = 4116121052 --[[item_filter_menu]]
UTIL_SF_WIN = 758265787 --[[win07_01_item_filter_list]]
UTIL_SF_LIST = 2569990914 --[[shop01_01_list_base]]
UTIL_SF_TABS = 4044286600 --[[cmn06_20_list_tab_item]]
UTIL_SF_ATTACH = 1887158505 --[[cmn06_01_list_tab_attach]]
UTIL_SF_KEY_MENU = 2640949932 -- param store: menu the window sends its params to (item_filter_menu OnInit)
UTIL_SF_KEY_INV = 2870353710 -- param store: inventory type = the window's tabs (nie.exe table 0x190BD00)
UTIL_SF_BUTTON = 3170216173 --[[CMD_FUNC2]] -- keyboard Tab, the bank's filter key (free on the shop list layer)
UTIL_SF_BTN_TEXT = 2352215829 -- menu_text "<CMD_FUNC2>" (the retail key glyph of the window's reset button)
UTIL_SF_CMD_SET = 2590880721 --[[CMND_UTIL_SHOP_FILTER_SET]]
UTIL_SF_CMD_RESET = 1387630434 --[[CMND_UTIL_SHOP_FILTER_RESET]]
UTIL_SF_LOG = 3661580131 --[[CMND_EVT_LOG]]
-- shop slot type (tab, 0x118BCA0) -> inventory type of the item filter window
UTIL_SF_INV = {[4] = 0, [5] = 1, [6] = 2, [7] = 3, [2] = 4, [3] = 5, [16] = 6, [17] = 11}
-- the window's defaults (item_filter_menu_inc CreateDefaultFilerParamArray: «all» of each category of the type)
UTIL_SF_DEFAULT = {[0] = {2}, [1] = {2}, [2] = {2}, [3] = {2}, [4] = {1}, [5] = {1}, [6] = {3, 4, 5}, [11] = {4, 6}}
UTIL_SF_PARAMS = {} -- slot -> retail filter params {listItemType, value, option} sent by the accept button
UTIL_SF_RECV = nil
UTIL_SF_CO = nil
UTIL_SF_LIVE = false
UTIL_SF_WAIT = 900
UTIL_SFB_LAYER = 4037719016 --[[shop01_11_view_staff]]
UTIL_SFB_TICK = 0
if UTIL_SF_WRAPPED == nil then
  UTIL_SF_WRAPPED = {}
end

function UTIL_SF_Log(...)
  pcall(funcLuaCommand, UTIL_SF_LOG, "utilities shop_filter", ...)
end

function UTIL_SF_Exists(m)
  return funcLuaMenuCommand(2231168902 --[[CMND_IS_EXIST_MENU_OBJECT?]], m) == true
end

function UTIL_SF_Slot()
  local ok, s = pcall(GetCurrentSlotType)
  if ok and s ~= nil then
    return s
  end
  return -1
end

function UTIL_SF_Flat(params)
  local t = {}
  for i = 1, #params do
    local p = params[i]
    t[#t + 1] = p.listItemType
    t[#t + 1] = p.value
    t[#t + 1] = p.option
  end
  return t
end

function UTIL_SF_Param(key, v)
  if funcLuaCommand(2947612279, key) then
    funcLuaCommand(3363400568, key)
  end
  funcLuaCommand(3860611758, key, 0, v, 1)
end

-- filter icon + key glyph in the grey end of the tab bar (retail meshes of cmn06_01_list_tab_attach that
-- shop_menu_buy hides; the equipment list shows the same pair)
function UTIL_SF_Icon(slot)
  local on = UTIL_SF_LIVE and UTIL_SF_INV[slot] ~= nil
  funcLuaMenuCommand(3405944500 --[[CMND_SET_MESH_VISIBLE]], UTIL_SF_ATTACH, 1037529311 --[[_icon_sort01]], on, 0)
  funcLuaMenuCommand(1505208242 --[[CMND_SET_MENU_TEXT_VISIBLE?]], UTIL_SF_ATTACH, 950238781 --[[_text_btn01]], on, 0)
  if on then
    local s = funcLuaCommand(4074371074 --[[CMND_TEXT_GET]], UTIL_SF_BTN_TEXT)
    funcLuaMenuCommand(1083631230 --[[CMND_SET_MENU_TEXT_STRING?]], UTIL_SF_ATTACH, 950238781 --[[_text_btn01]], s, 0)
  end
end

-- rebuild the rows of the current tab (the retail header -> list tab change: ChangeTab 0x543250 -> 0x118A100),
-- then top of the list and focus on its first row, as the retail ApplyItemFilter does after a filter
function UTIL_SF_Refresh()
  funcLuaMenuCommand(1262569306, UTIL_SF_TABS, UTIL_SF_LIST)
  funcLuaMenuCommand(306610847, UTIL_SF_LIST, 0)
  funcLuaMenuCommand(1778826357, 3747827324 --[[shop01_02_list_item]], 0, true)
end

function UTIL_SF_CanOpen()
  -- CLEAN_HUD_SS_CO: Clean HUD's shop shortcuts leaving the shop (nil without Clean HUD)
  if not UTIL_SF_LIVE or UTIL_SF_CO ~= nil or CLEAN_HUD_SS_CO ~= nil then
    return nil
  end
  local slot = UTIL_SF_Slot()
  local inv = UTIL_SF_INV[slot]
  if inv == nil then
    return nil
  end
  -- both menu control schemes (a list screen runs MENU_CTRL_WITH_ANALOG_MOVE_FOCUS; polling MENU_CTRL only never
  -- saw the key: 28/09 18:09 log)
  if funcLuaCommand(4265778440 --[[CMND_CHECK_INPUT_CMD]], 1332654303 --[[MENU_CTRL]], UTIL_SF_BUTTON) ~= true
    and funcLuaCommand(4265778440 --[[CMND_CHECK_INPUT_CMD]], 2748927068 --[[MENU_CTRL_WITH_ANALOG_MOVE_FOCUS]], UTIL_SF_BUTTON) ~= true then
    return nil
  end
  local why = nil
  if funcLuaCommand(1215256347 --[[CMND_BRIGHT_IS_FADE]]) == true then
    why = "fade"
  elseif UTIL_SF_Exists(968210065 --[[sub_window]]) then
    why = "sub_window"
  elseif UTIL_SF_Exists(449578137 --[[general_window]]) then
    why = "general_window"
  elseif UTIL_SF_Exists(UTIL_SF_MENU) then
    why = "filter open"
  elseif UTIL_SF_Exists(1427722143 --[[personal_plate_menu]]) then
    why = "personal plate"
  end
  if why ~= nil then
    UTIL_SF_Log("key ignored", slot, why)
    return nil
  end
  return slot, inv
end

-- the retail OpenFilter (item_filter_menu_inc) for the shop: params to the store, open the window, send the tab's
-- current params, wait for it to close; the params come back through OnReceiveFilterParam
function UTIL_SF_Open(slot, inv)
  funcLuaCommand(1917805374, 3848881948 --[[sy0000]])
  funcLuaMenuCommand(1558704558, UTIL_SF_SHOP, false)
  UTIL_SF_RECV = nil
  UTIL_SF_Param(UTIL_SF_KEY_MENU, UTIL_SF_SHOP)
  UTIL_SF_Param(UTIL_SF_KEY_INV, inv)
  UTIL_SF_Log("open", slot, inv)
  funcLuaCommand(433545986 --[[CMND_OPEN_MENU_OBJECT]], UTIL_SF_MENU)
  local n = 0
  while n < UTIL_SF_WAIT and funcLuaCommand(3693934564 --[[CMND_IS_OPEN_MENU_OBJECT]], UTIL_SF_MENU, UTIL_SF_WIN) ~= true do
    n = n + 1
    coroutine.yield()
  end
  local p = UTIL_SF_PARAMS[slot]
  if p == nil or #p == 0 then
    p = {}
    for _, c in ipairs(UTIL_SF_DEFAULT[inv] or {}) do
      p[#p + 1] = {listItemType = 8, value = c, option = 0}
    end
  end
  if #p > 0 then
    local flat = UTIL_SF_Flat(p)
    funcLuaMenuCommand(986162705 --[[CMND_SEND_ITEM_FILTER_PARAM]], UTIL_SF_MENU, #flat, flat)
  end
  while UTIL_SF_Exists(UTIL_SF_MENU) do
    coroutine.yield()
  end
  if UTIL_SF_RECV ~= nil then
    UTIL_SF_Apply(slot, inv, UTIL_SF_RECV)
    UTIL_SF_RECV = nil
  end
  funcLuaMenuCommand(1558704558, UTIL_SF_SHOP, true)
end

function UTIL_SF_Apply(slot, inv, params)
  local flat = UTIL_SF_Flat(params)
  local ok, live = pcall(funcLuaCommand, UTIL_SF_CMD_SET, slot, inv, table.unpack(flat))
  UTIL_SF_Log("apply", slot, inv, #params, ok and live)
  if not ok or live ~= true then
    return
  end
  UTIL_SF_PARAMS[slot] = params
  UTIL_SF_Refresh()
end

-- the window's params come back to the menu named in the param store (shop_menu) through these engine callbacks
function OnBeforeReceiveFilterParam()
  UTIL_SF_RECV = {}
end

function OnReceiveFilterParam(a1, a2, a3)
  if UTIL_SF_RECV == nil then
    UTIL_SF_RECV = {}
  end
  table.insert(UTIL_SF_RECV, {listItemType = a1, value = a2, option = a3})
end

function OnAfterReceiveFilterParam()
  -- applied by UTIL_SF_Open once the window has closed (the tab rebuild calls back into this script)
end

function UTIL_SF_Resume()
  local ok, err = coroutine.resume(UTIL_SF_CO)
  if not ok then
    UTIL_SF_Log("error", tostring(err))
    funcLuaMenuCommand(1558704558, UTIL_SF_SHOP, true)
  end
  if not ok or coroutine.status(UTIL_SF_CO) == "dead" then
    UTIL_SF_CO = nil
  end
end

function UTIL_SF_Reset()
  local ok, live, n = pcall(funcLuaCommand, UTIL_SF_CMD_RESET)
  UTIL_SF_LIVE = ok and live == true
  return ok and n or 0
end

function UTIL_SF_Tick()
  if UTIL_SF_CO ~= nil then
    UTIL_SF_Resume()
    return
  end
  local slot, inv = UTIL_SF_CanOpen()
  if slot ~= nil then
    UTIL_SF_CO = coroutine.create(UTIL_SF_Open)
    local ok, err = coroutine.resume(UTIL_SF_CO, slot, inv)
    if not ok then
      UTIL_SF_Log("error", tostring(err))
      funcLuaMenuCommand(1558704558, UTIL_SF_SHOP, true)
      UTIL_SF_CO = nil
    elseif coroutine.status(UTIL_SF_CO) == "dead" then
      UTIL_SF_CO = nil
    end
  end
end

function UTIL_SFB_Hide(inst)
  local i = inst or 0
  funcLuaMenuCommand(3405944500 --[[CMND_SET_MESH_VISIBLE]], UTIL_SFB_LAYER, 672386185 --[[_shop_cut_chr_dmy01]], false, i)
  funcLuaMenuCommand(3405944500 --[[CMND_SET_MESH_VISIBLE]], UTIL_SFB_LAYER, 2022610798 --[[_shop_cut_parts01]], false, i)
  funcLuaMenuCommand(711242136 --[[CMND_SET_LAYER_VISIBLE]], UTIL_SFB_LAYER, i, false)
end

function UTIL_SFB_Tick()
  UTIL_SFB_TICK = UTIL_SFB_TICK + 1
  if UTIL_SFB_TICK >= 20 then
    UTIL_SFB_TICK = 0
    if funcLuaMenuCommand(262659071 --[[CMND_IS_EXIST_LAYER?]], UTIL_SFB_LAYER) == true
      and funcLuaMenuCommand(1262717583 --[[CMND_IS_LAYER_VISIBLE]], UTIL_SFB_LAYER, 0) == true then
      UTIL_SFB_Hide(0)
    end
  end
end

-- wrap the callback `name`: make(orig) returns the wrapper. Through the framework's host when it is there (an
-- around handler: orig = the next one in the chain; `create`: hook it even if the script does not define it), else
-- the global itself (once per definition).
function UTIL_SF_Wrap(name, make, create)
  local H = VRFW_Host or EVT_Host
  if type(H) == "table" and type(H.on) == "function" then
    H.on("shop_menu_buy", name, {id = "utilities.shop_filter." .. name, phase = "around", create = create == true, fn = function(nxt, ...)
      return make(nxt)(...)
    end})
    return true
  end
  local cur = _ENV[name]
  if (type(cur) ~= "function" and create ~= true) or UTIL_SF_WRAPPED[cur] then
    return false
  end
  local w = make(cur)
  UTIL_SF_WRAPPED[w] = true
  _ENV[name] = w
  return true
end

UTIL_SF_Wrap("OnShopInit", function(orig)
  return function(...)
    local r = table.pack(orig(...))
    UTIL_SF_PARAMS = {}
    -- a filter left by a shop that never closed (title reset) would already have trimmed the first build
    if UTIL_SF_Reset() > 0 then
      UTIL_SF_Refresh()
    end
    UTIL_SF_Icon(UTIL_SF_Slot())
    return table.unpack(r, 1, r.n)
  end
end)

UTIL_SF_Wrap("FinalizeMenu", function(orig)
  return function(...)
    pcall(funcLuaCommand, UTIL_SF_CMD_RESET)
    if orig ~= nil then
      return orig(...)
    end
  end
end, true)

UTIL_SF_Wrap("UpdateTabNameByShopSlotType", function(orig)
  return function(a1, ...)
    local r = table.pack(orig(a1, ...))
    UTIL_SF_Icon(a1)
    return table.unpack(r, 1, r.n)
  end
end)

UTIL_SF_Wrap("Step", function(orig)
  return function(...)
    local r = table.pack(orig(...))
    UTIL_SF_Tick()
    UTIL_SFB_Tick()
    return table.unpack(r, 1, r.n)
  end
end)

UTIL_SF_Wrap("OnSetupLayer", function(orig)
  return function(a1, a2, ...)
    local r = table.pack(orig(a1, a2, ...))
    if a1 == UTIL_SFB_LAYER then
      UTIL_SFB_Hide(a2)
    end
    return table.unpack(r, 1, r.n)
  end
end)

UTIL_SF_Wrap("OnOpenLayer", function(orig)
  return function(a1, a2, ...)
    local r = table.pack(orig(a1, a2, ...))
    if a1 == UTIL_SFB_LAYER then
      UTIL_SFB_Hide(a2)
    end
    return table.unpack(r, 1, r.n)
  end
end)
